using System.Security.Cryptography;
using System.Text;
using Microsoft.Data.Sqlite;
namespace MizanDesktop.Services;
public sealed record FinancialSnapshot(decimal Sales,decimal SalesReturns,decimal Purchases,decimal PurchaseReturns,decimal Cogs,decimal Expenses,decimal GrossProfit,decimal NetProfit,decimal Receivables,decimal Payables);
public sealed record PartyBalance(string Name,string Type,decimal Balance);
public sealed class EnterpriseAccountingService{
 readonly string cs;
 public EnterpriseAccountingService(){var d=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MizanDesktop");Directory.CreateDirectory(d);cs=$"Data Source={Path.Combine(d,"mizan.db")}";EnsureSchema();}
 SqliteConnection Open(){var c=new SqliteConnection(cs);c.Open();return c;}
 static void Add(SqliteConnection c,string t,string n,string d){using var q=c.CreateCommand();q.CommandText=$"ALTER TABLE {t} ADD COLUMN {n} {d}";try{q.ExecuteNonQuery();}catch(SqliteException e)when(e.SqliteErrorCode==1){}}
 public static string HashPin(string s)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(s)));
 static string Hash(string s)=>HashPin(s);
 void EnsureSchema(){using var c=Open();using var q=c.CreateCommand();q.CommandText=@"CREATE TABLE IF NOT EXISTS Users(Id TEXT PRIMARY KEY,Name TEXT NOT NULL UNIQUE,Role TEXT NOT NULL,PinHash TEXT,IsActive INTEGER NOT NULL DEFAULT 1,CreatedAt TEXT NOT NULL);CREATE TABLE IF NOT EXISTS CashClosings(Id TEXT PRIMARY KEY,FundId TEXT,ClosedAt TEXT,OpeningBalance REAL,InTotal REAL,OutTotal REAL,ExpectedBalance REAL,ActualBalance REAL,Difference REAL,ClosedBy TEXT,Notes TEXT);CREATE TABLE IF NOT EXISTS AppSessions(Id TEXT PRIMARY KEY,UserId TEXT,LoginAt TEXT,LogoutAt TEXT);CREATE TABLE IF NOT EXISTS ReversalEntries(Id TEXT PRIMARY KEY,OriginalEntryId TEXT,Reason TEXT,CreatedAt TEXT,CreatedBy TEXT);";q.ExecuteNonQuery();Add(c,"Invoices","CancelledAt","TEXT");Add(c,"Invoices","CancelledBy","TEXT");Add(c,"Invoices","CancelReason","TEXT");Add(c,"Invoices","ReversalEntryId","TEXT");Add(c,"Payments","Cancelled","INTEGER NOT NULL DEFAULT 0");Add(c,"Payments","Currency","TEXT NOT NULL DEFAULT 'SYP'");Add(c,"Payments","FundId","TEXT NOT NULL DEFAULT 'MAIN-SYP'");q.CommandText="SELECT COUNT(*) FROM Users";if(Convert.ToInt32(q.ExecuteScalar())==0){q.CommandText="INSERT INTO Users(Id,Name,Role,PinHash,IsActive,CreatedAt) VALUES('admin','admin','ADMIN',$p,1,$d)";q.Parameters.AddWithValue("$p",Hash("1234"));q.Parameters.AddWithValue("$d",DateTime.Now.ToString("O"));q.ExecuteNonQuery();}}
 public (string Id,string Name,string Role)? Login(string name,string pin){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT Id,Name,Role,PinHash FROM Users WHERE Name=$n AND IsActive=1";q.Parameters.AddWithValue("$n",name);using var r=q.ExecuteReader();if(!r.Read())return null;var id=r.GetString(0);var stored=r.IsDBNull(3)?"":r.GetString(3);var hash=Hash(pin);if(!string.Equals(stored,hash,StringComparison.OrdinalIgnoreCase)){if(!string.Equals(stored,pin,StringComparison.Ordinal)){return null;}using var u=c.CreateCommand();u.CommandText="UPDATE Users SET PinHash=$p WHERE Id=$i";u.Parameters.AddWithValue("$p",hash);u.Parameters.AddWithValue("$i",id);u.ExecuteNonQuery();}return(id,r.GetString(1),r.GetString(2));}
 public bool HasPermission(string role,string p)=>role switch{"ADMIN"=>true,"SUPERVISOR"=>p is not "USERS" and not "IMPORT" and not "SETTINGS","CASHIER"=>p is "SALES" or "PURCHASES" or "CASH" or "PRODUCTS" or "PARTIES",_=>false};
 public FinancialSnapshot Financials(DateTime f,DateTime t){using var c=Open();decimal S(int type){using var q=c.CreateCommand();q.CommandText="SELECT COALESCE(SUM(Total),0) FROM Invoices WHERE Type=$x AND Date>=$f AND Date<$t AND Status<>'CANCELLED'";q.Parameters.AddWithValue("$x",type);q.Parameters.AddWithValue("$f",f.ToString("O"));q.Parameters.AddWithValue("$t",t.ToString("O"));return Convert.ToDecimal(q.ExecuteScalar() ?? 0, System.Globalization.CultureInfo.InvariantCulture);}var sales=S(0);var sr=S(2);var pur=S(1);var pr=S(3);decimal cogs=0;using(var q=c.CreateCommand()){q.CommandText="SELECT COALESCE(SUM(CASE WHEN i.Type=0 THEN l.Quantity*l.UnitCost WHEN i.Type=2 THEN -l.Quantity*l.UnitCost ELSE 0 END),0) FROM InvoiceLines l JOIN Invoices i ON i.Id=l.InvoiceId WHERE i.Type IN (0,2) AND i.Status<>'CANCELLED' AND i.Date>=$f AND i.Date<$t";q.Parameters.AddWithValue("$f",f.ToString("O"));q.Parameters.AddWithValue("$t",t.ToString("O"));cogs=Convert.ToDecimal(q.ExecuteScalar() ?? 0, System.Globalization.CultureInfo.InvariantCulture);}decimal exp=0;using(var q=c.CreateCommand()){q.CommandText="SELECT COALESCE(SUM(Amount),0) FROM Payments WHERE Type=3 AND Cancelled=0 AND Date>=$f AND Date<$t";q.Parameters.AddWithValue("$f",f.ToString("O"));q.Parameters.AddWithValue("$t",t.ToString("O"));exp=Convert.ToDecimal(q.ExecuteScalar() ?? 0, System.Globalization.CultureInfo.InvariantCulture);}decimal ar=0,ap=0;using(var q=c.CreateCommand()){q.CommandText="SELECT COALESCE(SUM(CASE WHEN Type=0 AND Balance>0 THEN Balance ELSE 0 END),0),COALESCE(SUM(CASE WHEN Type=1 AND Balance>0 THEN Balance ELSE 0 END),0) FROM Parties";using var r=q.ExecuteReader();if(r.Read()){ar=(decimal)r.GetDouble(0);ap=(decimal)r.GetDouble(1);}}var gross=sales-sr-cogs;return new(sales,sr,pur,pr,cogs,exp,gross,gross-exp,ar,ap);}
 public List<AccountBalance> TrialBalance(){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT Account,SUM(Debit),SUM(Credit) FROM JournalLines jl JOIN JournalEntries je ON je.Id=jl.EntryId GROUP BY Account ORDER BY Account";using var r=q.ExecuteReader();var a=new List<AccountBalance>();while(r.Read()){var d=(decimal)r.GetDouble(1);var cr=(decimal)r.GetDouble(2);a.Add(new(r.GetString(0),d,cr));}return a;}
 public List<PartyBalance> PartyBalances(){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT Name,CASE WHEN Type=0 THEN 'عميل' ELSE 'مورد' END,Balance FROM Parties ORDER BY Name";using var r=q.ExecuteReader();var a=new List<PartyBalance>();while(r.Read())a.Add(new(r.GetString(0),r.GetString(1),(decimal)r.GetDouble(2)));return a;}
 public void CancelInvoice(Guid id,string user,string reason){using var c=Open();using var tx=c.BeginTransaction();string no="",party="",status="";int type;double total,paid;using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="SELECT Number,Type,PartyId,Total,PaidAmount,Status FROM Invoices WHERE Id=$i";q.Parameters.AddWithValue("$i",id.ToString());using var r=q.ExecuteReader();if(!r.Read())throw new InvalidOperationException("الفاتورة غير موجودة");no=r.GetString(0);type=r.GetInt32(1);party=r.GetString(2);total=r.GetDouble(3);paid=r.GetDouble(4);status=r.GetString(5);}if(status=="CANCELLED")throw new InvalidOperationException("الفاتورة ملغاة مسبقًا");var oldEntry="";using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="SELECT Id FROM JournalEntries WHERE Reference=$r ORDER BY Date DESC LIMIT 1";q.Parameters.AddWithValue("$r",no);oldEntry=Convert.ToString(q.ExecuteScalar())??"";}var rev=Guid.NewGuid().ToString();using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="INSERT INTO JournalEntries VALUES($i,$d,$x,$r)";q.Parameters.AddWithValue("$i",rev);q.Parameters.AddWithValue("$d",DateTime.Now.ToString("O"));q.Parameters.AddWithValue("$x","قيد عكسي - "+no);q.Parameters.AddWithValue("$r","REV:"+no);q.ExecuteNonQuery();}if(oldEntry!=""){using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="INSERT INTO JournalLines(EntryId,Account,Debit,Credit) SELECT $n,Account,Credit,Debit FROM JournalLines WHERE EntryId=$o";q.Parameters.AddWithValue("$n",rev);q.Parameters.AddWithValue("$o",oldEntry);q.ExecuteNonQuery();}using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="SELECT ProductId,Quantity FROM InvoiceLines WHERE InvoiceId=$i";q.Parameters.AddWithValue("$i",id.ToString());using var r=q.ExecuteReader();var rows=new List<(string,double)>();while(r.Read())rows.Add((r.GetString(0),r.GetDouble(1)));foreach(var z in rows){var d=type is 0 or 3?z.Item2:-z.Item2;using var u=c.CreateCommand();u.Transaction=tx;u.CommandText="UPDATE Products SET Quantity=Quantity+$d WHERE Id=$i";u.Parameters.AddWithValue("$d",d);u.Parameters.AddWithValue("$i",z.Item1);u.ExecuteNonQuery();}}if(party!=""){var sign=type switch{0=>-1,1=>1,2=>1,3=>-1,_=>0};using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="UPDATE Parties SET Balance=Balance+$d WHERE Id=$i";q.Parameters.AddWithValue("$d",(total-paid)*sign);q.Parameters.AddWithValue("$i",party);q.ExecuteNonQuery();}using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="UPDATE Invoices SET Status='CANCELLED',CancelledAt=$d,CancelledBy=$u,CancelReason=$r,ReversalEntryId=$e WHERE Id=$i";q.Parameters.AddWithValue("$d",DateTime.Now.ToString("O"));q.Parameters.AddWithValue("$u",user);q.Parameters.AddWithValue("$r",reason);q.Parameters.AddWithValue("$e",rev);q.Parameters.AddWithValue("$i",id.ToString());q.ExecuteNonQuery();}using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="UPDATE Payments SET Cancelled=1 WHERE InvoiceId=$i AND Cancelled=0";q.Parameters.AddWithValue("$i",id.ToString());q.ExecuteNonQuery();}using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="UPDATE CashTransactions SET IsCancelled=1 WHERE ReferenceId=$i AND IsCancelled=0";q.Parameters.AddWithValue("$i",id.ToString());q.ExecuteNonQuery();}using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="INSERT INTO AuditLogs(Id,Action,EntityType,EntityId,Description,PerformedBy,Timestamp) VALUES($id,'INVOICE_CANCEL','INVOICE',$e,$d,$u,$ts)";q.Parameters.AddWithValue("$id",Guid.NewGuid().ToString());q.Parameters.AddWithValue("$e",id.ToString());q.Parameters.AddWithValue("$d",$"إلغاء الفاتورة {no}: {reason}");q.Parameters.AddWithValue("$u",user);q.Parameters.AddWithValue("$ts",DateTime.Now.ToString("O"));q.ExecuteNonQuery();}using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="INSERT INTO ReversalEntries VALUES($i,$o,$r,$d,$u)";q.Parameters.AddWithValue("$i",Guid.NewGuid().ToString());q.Parameters.AddWithValue("$o",oldEntry);q.Parameters.AddWithValue("$r",reason);q.Parameters.AddWithValue("$d",DateTime.Now.ToString("O"));q.Parameters.AddWithValue("$u",user);q.ExecuteNonQuery();}tx.Commit();}
 public void CloseCash(string fund,decimal actual,string user){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT OpeningBalance+COALESCE((SELECT SUM(CASE WHEN Type IN ('IN','TRANSFER_IN') THEN Amount ELSE -Amount END) FROM CashTransactions WHERE FundId=f.Id AND IsCancelled=0),0) FROM CashFunds f WHERE Id=$f";q.Parameters.AddWithValue("$f",fund);var expected=Convert.ToDecimal(q.ExecuteScalar() ?? 0, System.Globalization.CultureInfo.InvariantCulture);using var i=c.CreateCommand();i.CommandText="INSERT INTO CashClosings VALUES($i,$f,$d,0,0,0,$e,$a,$x,$u,'إغلاق يدوي')";i.Parameters.AddWithValue("$i",Guid.NewGuid().ToString());i.Parameters.AddWithValue("$f",fund);i.Parameters.AddWithValue("$d",DateTime.Now.ToString("O"));i.Parameters.AddWithValue("$e",(double)expected);i.Parameters.AddWithValue("$a",(double)actual);i.Parameters.AddWithValue("$x",(double)(actual-expected));i.Parameters.AddWithValue("$u",user);i.ExecuteNonQuery();}
 public AndroidImportReport ImportAndroid(string file)=>new AndroidDatabaseImporter().Import(file);
 static string? Table(SqliteConnection c,string[] names){foreach(var n in names){using var q=c.CreateCommand();q.CommandText="SELECT name FROM sqlite_master WHERE type='table' AND lower(name)=lower($n)";q.Parameters.AddWithValue("$n",n);if(q.ExecuteScalar()!=null)return n;}return null;}
 static void Import(SqliteConnection s,SqliteConnection d,SqliteTransaction tx,string dest,(string,string,string) candidates,string[] nameCols){var t=Table(s,new[]{candidates.Item1,candidates.Item2,candidates.Item3});if(t==null)return;using var q=s.CreateCommand();q.CommandText=$"SELECT * FROM [{t}] LIMIT 100000";using var r=q.ExecuteReader();var map=Enumerable.Range(0,r.FieldCount).ToDictionary(i => r.GetName(i), StringComparer.OrdinalIgnoreCase);while(r.Read()){string V(params string[] n){foreach(var x in n)if(map.TryGetValue(x,out var i)&&!r.IsDBNull(i))return Convert.ToString(r.GetValue(i))??"";return "";}var name=V(nameCols);if(name=="")continue;var id=V("id",dest=="Products"?"product_id":"party_id");if(id=="")id=Guid.NewGuid().ToString();using var ins=d.CreateCommand();ins.Transaction=tx;if(dest=="Products"){double.TryParse(V("quantity","stock","qty"),out var qty);double.TryParse(V("purchase_price","cost"),out var pp);double.TryParse(V("sale_price","price"),out var sp);ins.CommandText="INSERT INTO Products(Id,Code,Barcode,Name,Unit,PurchasePrice,SalePrice,Quantity,MinQuantity,IsActive) VALUES($i,$c,$b,$n,$u,$pp,$sp,$q,0,1) ON CONFLICT(Id) DO UPDATE SET Name=$n,PurchasePrice=$pp,SalePrice=$sp,Quantity=$q";ins.Parameters.AddWithValue("$c",V("code","sku"));ins.Parameters.AddWithValue("$b",V("barcode"));ins.Parameters.AddWithValue("$u",V("unit"));ins.Parameters.AddWithValue("$pp",pp);ins.Parameters.AddWithValue("$sp",sp);ins.Parameters.AddWithValue("$q",qty);}else{double.TryParse(V("balance","opening_balance"),out var bal);ins.CommandText="INSERT INTO Parties(Id,Name,Phone,Address,Type,Balance) VALUES($i,$n,$p,$a,0,$b) ON CONFLICT(Id) DO UPDATE SET Name=$n,Phone=$p,Address=$a,Balance=$b";ins.Parameters.AddWithValue("$p",V("phone","mobile"));ins.Parameters.AddWithValue("$a",V("address"));ins.Parameters.AddWithValue("$b",bal);}ins.Parameters.AddWithValue("$i",id);ins.Parameters.AddWithValue("$n",name);ins.ExecuteNonQuery();}}
}
